# ═══ BOOT: EMB REGISTRY + VIRTUAL-PATH OPENERS ═══

# ══════════════════════════════════════════════════════════════════════════════
# EMBEDDED PAYLOAD REGISTRY — every dataset ships inside this file.
# Values are ":emb:<name>" virtual paths; zlib+base64 at rest, decoded once.
# ══════════════════════════════════════════════════════════════════════════════

import base64 as _b64mod
import io as _iomod
import json as _jsonmod
import os
import sys
import zlib as _zlibmod

_AB_EMB_NAMES = ("zeros50k", "golden", "golden_stk", "mon", "rh_sp", "rh_v5")


def _emb_decode(name):
    """Decode one embedded blob: strip whitespace → b64 → zlib inflate → bytes."""
    raw = getattr(_AB_EMB_SRC, name)
    return _zlibmod.decompress(_b64mod.b64decode("".join(raw.split())))


_EMB = {}


def _emb_bytes(name):
    if name not in _EMB:
        _EMB[name] = _emb_decode(name)
    return _EMB[name]


def _emb_text(name):
    return _emb_bytes(name).decode("utf-8")


def _ab_open_text(path, encoding="utf-8", errors="strict"):
    """Virtual-path-aware text opener: ':emb:*' reads the embedded registry,
    real paths fall through to the filesystem (parity with the package port)."""
    p = os.fspath(path)
    if p.startswith(":emb:"):
        return _iomod.StringIO(_emb_text(p[5:]))
    return open(p, "r", encoding=encoding, errors=errors)


def _ab_load_json_emb(vpath):
    """Load an embedded JSON payload into a dict."""
    return _jsonmod.loads(_emb_text(vpath[5:] if vpath.startswith(":emb:") else vpath))


def _ab_load_zeros_emb(vpath):
    """Load whitespace-separated floats from an embedded or real zeros file."""
    try:
        text = _emb_text(vpath[5:]) if vpath.startswith(":emb:") else None
        if text is None:
            with open(vpath, "r", encoding="utf-8", errors="replace") as fh:
                text = fh.read()
    except OSError:
        return []
    out = []
    for tok in text.split():
        try:
            out.append(float(tok))
        except ValueError:
            pass
    out.sort()
    return out


# ═══ KERNEL MODULE: mt19937 ═══

# -*- coding: utf-8 -*-
"""Classic MT19937 (init_genrand) — bit-identical across the language ports.

Julia's MersenneTwister is dSFMT-based and NOT reproducible outside Julia, so
the golden layer substitutes this classic MT19937 everywhere (see
ports/golden/gen_golden.jl). The double conversion is the CPython one:

    random() = ((a >> 5) * 2**26 + (b >> 6)) / 2**53     # two draws per double
"""

from math import log, cos, pi

mt19937__N = 624
mt19937__M = 397
mt19937__MATRIX_A = 0x9908B0DF
mt19937__UPPER = 0x80000000
mt19937__LOWER = 0x7FFFFFFF


class mt19937_MT19937(object):
    """Classic MT19937 with the mt19937ar reference block semantics."""

    def __init__(self, seed=5489):
        if isinstance(seed, float):
            # accept Julia-style UInt32 seeds passed as floats
            seed = int(seed) & 0xFFFFFFFF
        self.mt = [0] * mt19937__N
        self.mt[0] = seed & 0xFFFFFFFF
        for i in range(1, mt19937__N):
            prev = self.mt[i - 1]
            self.mt[i] = (1812433253 * (prev ^ (prev >> 30)) + i) & 0xFFFFFFFF
        # mt19937ar reference: first draw triggers the twist (idx past the end)
        self.idx = mt19937__N

    def next_u32(self):
        if self.idx >= mt19937__N:
            for kk in range(mt19937__N):
                y = (self.mt[kk] & mt19937__UPPER) | (self.mt[(kk + 1) % mt19937__N] & mt19937__LOWER)
                nxt = self.mt[(kk + mt19937__M) % mt19937__N] ^ (y >> 1)
                if y & 1:
                    nxt ^= mt19937__MATRIX_A
                self.mt[kk] = nxt
            self.idx = 0
        y = self.mt[self.idx]
        self.idx += 1
        y ^= y >> 11
        y ^= (y << 7) & 0x9D2C5680
        y ^= (y << 15) & 0xEFC60000
        y ^= y >> 18
        return y & 0xFFFFFFFF

    def random(self):
        """[0,1) double from two draws — identical to CPython random.random()."""
        a = self.next_u32() >> 5
        b = self.next_u32() >> 6
        return (a * 67108864.0 + b) / 9007199254740992.0

    def randn(self):
        """Box-Muller normal draw: u1<=0 is redrawn (u2 NOT consumed on redraw).

        Mirrors Random.randn on the MT19937RNG shim in gen_golden.jl.
        """
        u1 = self.random()
        while u1 <= 0.0:
            u1 = self.random()
        u2 = self.random()
        return (-2.0 * log(u1)) ** 0.5 * cos(2.0 * pi * u2)

    def rand_u8(self):
        """rand(rng, UInt8): top 8 bits of the next UInt32."""
        return self.next_u32() >> 24


# ═══ KERNEL MODULE: special ═══

# -*- coding: utf-8 -*-
"""Scalar special functions — 1:1 with ab_cloud_full.jl §3.

Lanczos lgamma (g=7, n=9), regularized lower incomplete gamma (series +
Lentz continued fraction), chi2 CDF, Kolmogorov-Smirnov asymptotic p-value,
GOE/GUE₂ Wigner surmises, Lambert W (Halley), Gram points, b(N) statistic.
"""

from math import log, sin, cos, sqrt, exp, fabs, pi, isnan

special__LANCZOS_COEF = (
    0.99999999999980993, 676.5203681218851, -1259.1392167224028,
    771.32342877765313, -176.61502916214059, 12.507343278686905,
    -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7,
)


def special_lgamma_lanczos(x):
    if x < 0.5:
        return log(pi / sin(pi * x)) - special_lgamma_lanczos(1.0 - x)
    x -= 1.0
    a = special__LANCZOS_COEF[0]
    t = x + 7.0 + 0.5
    for i in range(1, 8):
        a += special__LANCZOS_COEF[i] / (x + i)
    return 0.5 * log(2 * pi) + (x + 0.5) * log(t) - t + log(a)


def special_gammp_series(a, x):
    ap = a
    total = 1.0 / a
    delta = total
    for _ in range(200):
        ap += 1.0
        delta *= x / ap
        total += delta
        if fabs(delta) < fabs(total) * 1e-15:
            break
    return total * exp(-x + a * log(x) - special_lgamma_lanczos(a))


def special_gammq_cf(a, x):
    FPMIN = 1e-300
    b = x + 1.0 - a
    c = 1.0 / FPMIN
    d = 1.0 / b
    h = d
    for i in range(1, 201):
        an = -float(i) * (i - a)
        b += 2.0
        d = an * d + b
        if fabs(d) < FPMIN:
            d = FPMIN
        c = b + an / c
        if fabs(c) < FPMIN:
            c = FPMIN
        d = 1.0 / d
        delta = d * c
        h *= delta
        if fabs(delta - 1.0) < 1e-15:
            break
    return exp(-x + a * log(x) - special_lgamma_lanczos(a)) * h


def special_regularized_gamma_p(a, x):
    if x <= 0.0:
        return 0.0
    if x < a + 1.0:
        return special_gammp_series(a, x)
    return 1.0 - special_gammq_cf(a, x)


def special_chi2_cdf(x, df):
    return special_regularized_gamma_p(df / 2.0, x / 2.0)


def special_ks_asymptotic_pvalue(lam):
    if lam <= 0.0:
        return 1.0
    if lam < 0.6:
        s2 = 0.0
        for k in range(1, 1001):
            term2 = exp(-(((2.0 * k - 1.0) * (2.0 * k - 1.0)) * pi * pi)
                        / (8.0 * lam * lam))
            s2 += term2
            if term2 < 1e-18:
                break
        v = 1.0 - sqrt(2 * pi) / lam * s2
        return 0.0 if v < 0.0 else (1.0 if v > 1.0 else v)
    s = 0.0
    sign = 1.0
    for k in range(1, 101):
        term = sign * exp(-2.0 * k * k * lam * lam)
        s += term
        sign = -sign
        if fabs(term) < 1e-18:
            break
    v = 2.0 * s
    return 0.0 if v < 0.0 else (1.0 if v > 1.0 else v)


def special_goe_surmise_cdf(s):
    return 1.0 - exp(-pi * s * s / 4.0)


def special_gue2_surmise_cdf(s):
    if s < 0:
        return 0.0
    x2 = 4.0 * s * s / pi
    return special_regularized_gamma_p(0.5, x2) - (4.0 * s / pi) * exp(-x2)


def special_gue2_surmise_pdf(s):
    return (32.0 / (pi * pi)) * s * s * exp(-4.0 * s * s / pi)


def special_lambert_w(x):
    """W0 branch, Newton-Halley — verbatim with the Julia original."""
    if x <= -1.0 / exp(1.0):
        return -1.0
    w = x if x < 1.5 else log(x) - log(log(x))
    for _ in range(50):
        ew = exp(w)
        f = w * ew - x
        fp = ew * (w + 1.0)
        fpp = ew * (w + 2.0)
        delta = -f / (fp - 0.5 * f * fpp / fp)
        w += delta
        if fabs(delta) < 1e-15 * fabs(w):
            break
    return w


def special_gram_point(n):
    """Gram point g_n: theta(t) = n*pi solved by 8 Newton steps."""
    if n <= 0:
        return 0.0
    t = 2 * pi * float(n) / special_lambert_w(float(n) / exp(1.0))
    for _ in range(8):
        arg = t / (2 * pi)
        if arg <= 0:
            break
        theta = (t / 2 * log(arg) - t / 2 - pi / 8 + 1.0 / (48 * t)
                 + 7.0 / (5760 * t * t * t))
        dtheta = 0.5 * log(arg) - 1.0 / (48 * t * t) - 21.0 / (5760 * t ** 4)
        if fabs(dtheta) < 1e-30:
            break
        t -= (theta - float(n) * pi) / dtheta
    return t


def special_compute_bN(z, N, offset=0):
    """b(N) = <|gamma_k - g_k|> over the first N zeros."""
    N = min(N, len(z))
    s = 0.0
    for k in range(1, N + 1):
        s += fabs(z[k - 1] - special_gram_point(offset + k))
    return s / float(N)


# ═══ KERNEL MODULE: rmt_table ═══

# -*- coding: utf-8 -*-
"""RMT reference-law engine — 32768-point GUE2 CDF table + exact-law sampler.

The Julia original evaluates gue_cdf analytically (openlibm); the ports use
a 32768-point table on [0, 5] with linear interpolation (|dF| <= 1e-9, inside
the 1e-7 cross-libm tolerance). The exact-law sampler for Test 11 uses a
4096-point quantile grid built by 48-step bisection.

set_spacing_law('gue2' | 'goe') mirrors the Julia Ref{Symbol} law switch.
"""


rmt_table__TN = 32768
rmt_table__QN = 4096
rmt_table__SMAX = 5.0


class rmt_table__RmtTable(object):
    def __init__(self):
        self.law = 0          # 0 = gue2, 1 = goe
        self.table_on = True
        self._cdf = None      # lazily built
        self._quant = None
        self._quant_umax = None

    # -- law handling -------------------------------------------------------
    def set_spacing_law(self, name):
        name = name.lower()
        if name in ("gue2", "gue", "gue2_surmise"):
            self.law = 0
        elif name in ("goe", "goe_surmise"):
            self.law = 1
        else:
            raise ValueError("unknown spacing law: %r" % (name,))

    # -- CDF ----------------------------------------------------------------
    @staticmethod
    def gue2_exact(s):
        return special_gue2_surmise_cdf(s)

    def _build_cdf(self):
        self._cdf = [self.gue2_exact(i * rmt_table__SMAX / (rmt_table__TN - 1)) for i in range(rmt_table__TN)]

    def table_cdf(self, s):
        if s < 0:
            return 0.0
        if self.law == 1:
            return special_goe_surmise_cdf(s)
        if self._cdf is None:
            self._build_cdf()
        if s >= rmt_table__SMAX:
            return self.gue2_exact(s)
        x = s * (rmt_table__TN - 1) / rmt_table__SMAX
        i = int(x)          # floor for s >= 0
        if i < 0 or i >= rmt_table__TN - 1:
            return self.gue2_exact(s)
        t = x - i
        return (1.0 - t) * self._cdf[i] + t * self._cdf[i + 1]

    def gue_cdf(self, s):
        if self.law == 1:
            return special_goe_surmise_cdf(s)
        if self.table_on:
            return self.table_cdf(s)
        return self.gue2_exact(s)

    # -- exact-law sampler ---------------------------------------------------
    def _build_quant(self):
        self._quant_umax = self.gue_cdf(rmt_table__SMAX)
        q = [0.0] * (rmt_table__QN + 1)
        for j in range(rmt_table__QN + 1):
            u = self._quant_umax * float(j) / rmt_table__QN
            lo, hi = 0.0, rmt_table__SMAX
            for _ in range(48):
                mid = 0.5 * (lo + hi)
                if self.gue_cdf(mid) < u:
                    lo = mid
                else:
                    hi = mid
            q[j] = 0.5 * (lo + hi)
        self._quant = q

    def sample(self, rng, out):
        """Fill list `out` with draws from the active spacing law (in place)."""
        if self._quant is None:
            self._build_quant()
        q = self._quant
        for k in range(len(out)):
            x = rng.random() * rmt_table__QN
            j = int(x)
            if j > rmt_table__QN - 1:
                j = rmt_table__QN - 1
            if j < 0:
                j = 0
            t = x - j
            if t > 1.0:
                t = 1.0
            out[k] = (1.0 - t) * q[j] + t * q[j + 1]


rmt_table_RMT = rmt_table__RmtTable()          # active reference law (process-wide, like the Julia Ref)


def rmt_table_set_spacing_law(name):
    rmt_table_RMT.set_spacing_law(name)


def rmt_table_gue_cdf(s):
    return rmt_table_RMT.gue_cdf(s)


def rmt_table_rmt_sample(rng, out):
    rmt_table_RMT.sample(rng, out)


# ═══ KERNEL MODULE: gof ═══

# -*- coding: utf-8 -*-
"""GOF tests + long-range spectral statistics — 1:1 with ab_cloud_full.jl §4-5.

KS / Cramer-von Mises / Anderson-Darling / chi2 against the GUE reference
law, mean adjacent spacing ratio, unfolded positions, number variance S2(L),
spectral rigidity Delta3(L), two-level form factor K(t).
"""

from math import log, sqrt, fabs, pi, cos, sin, nan, isnan, floor
from bisect import bisect_left



def gof_normalized_spacings(z):
    """delta_k * rho(t_k) with rho(t) = log(t/2pi)/2pi (strictly positive t)."""
    sp = []
    for k in range(len(z) - 1):
        if z[k] <= 0:
            continue
        sp.append((z[k + 1] - z[k]) * log(z[k] / (2 * pi)) / (2 * pi))
    return sp


class gof_Linreg(object):
    __slots__ = ("a", "b", "R2", "se_b", "res")

    def __init__(self):
        self.a = self.b = self.R2 = 0.0
        self.se_b = nan
        self.res = []

    def __iter__(self):
        """Tuple-style unpacking: a, b, R2, se, res = linreg(x, y)."""
        return iter((self.a, self.b, self.R2, self.se_b, self.res))


def gof_linreg(x, y):
    n = len(x)
    r = gof_Linreg()
    if n == 0:
        return r
    mx = sum(x) / n
    my = sum(y) / n
    Sxx = sum((xi - mx) * (xi - mx) for xi in x)
    Sxy = sum((xi - mx) * (yi - my) for xi, yi in zip(x, y))
    if Sxx == 0.0 or n < 2:
        r.a = r.b = r.R2 = 0.0
        r.se_b = nan
        r.res = [0.0] * n
        return r
    r.b = Sxy / Sxx
    r.a = my - r.b * mx
    r.res = [yi - (r.a + r.b * xi) for xi, yi in zip(x, y)]
    ss_res = sum(e * e for e in r.res)
    ss_tot = sum((yi - my) * (yi - my) for yi in y)
    r.R2 = 1.0 - ss_res / ss_tot if ss_tot > 0 else 0.0
    r.se_b = sqrt(ss_res / ((n - 2) * Sxx)) if (n > 2 and Sxx > 0) else nan
    return r


def gof_ks_test(sp, cdf_func=None):
    n = len(sp)
    s = sorted(sp)
    cdf = cdf_func if cdf_func is not None else rmt_table_RMT.gue_cdf
    D = 0.0
    for i in range(1, n + 1):
        F = cdf(s[i - 1])
        D = max(D, fabs(i / n - F), fabs((i - 1) / n - F))
    lam = (sqrt(n) + 0.12 + 0.11 / sqrt(n)) * D
    return D, special_ks_asymptotic_pvalue(lam)


def gof_cvm_test(sp):
    n = len(sp)
    s = sorted(sp)
    W2 = 0.0
    for i in range(1, n + 1):
        u = rmt_table_RMT.gue_cdf(s[i - 1])
        d = u - (2.0 * i - 1.0) / (2.0 * n)
        W2 += d * d
    return W2 + 1.0 / (12.0 * n)


def gof_anderson_darling_stat(sp):
    n = len(sp)
    s = sorted(sp)
    acc = 0.0
    for i in range(1, n + 1):
        Fi = rmt_table_RMT.gue_cdf(s[i - 1])
        Fni = rmt_table_RMT.gue_cdf(s[n - i])
        Fi = min(max(Fi, 1e-300), 1.0 - 1e-16)
        Fni = min(max(Fni, 1e-300), 1.0 - 1e-16)
        acc += (2.0 * i - 1.0) * (log(Fi) + log(1.0 - Fni))
    return -n - acc / n


def gof_chi2_gue_test(sp, nbins):
    s = sorted(sp)
    s_max = min(s[-1], 4.0)
    obs = [0] * nbins
    for v in s:
        if v >= s_max:
            obs[nbins - 1] += 1
        else:
            b = min(int(floor(v / s_max * nbins)) + 1, nbins)
            obs[b - 1] += 1
    N = len(s)
    edges = [s_max * i / nbins for i in range(nbins + 1)]
    chi2 = 0.0
    df = 0
    for i in range(1, nbins + 1):
        if i < nbins:
            ec = N * (rmt_table_RMT.gue_cdf(edges[i]) - rmt_table_RMT.gue_cdf(edges[i - 1]))
        else:
            ec = N * (1.0 - rmt_table_RMT.gue_cdf(edges[i - 1]))
        if ec < 5:
            continue
        chi2 += (obs[i - 1] - ec) * (obs[i - 1] - ec) / ec
        df += 1
    df = max(df - 1, 1)
    return chi2, df, 1.0 - special_chi2_cdf(chi2, df)


def gof_mean_adjacent_spacing_ratio(eigs):
    n = len(eigs)
    if n < 3:
        return nan, 0
    s = sorted(eigs)
    d = [s[i + 1] - s[i] for i in range(n - 1)]
    if len(d) < 2:
        return nan, 0
    acc = 0.0
    cnt = 0
    for i in range(len(d) - 1):
        a, b = d[i], d[i + 1]
        if a == 0.0 and b == 0.0:
            continue
        acc += min(a, b) / max(a, b)
        cnt += 1
    if cnt <= 0:
        return nan, 0
    return acc / cnt, cnt


def gof__smooth_counting_function(T):
    if T <= 0.0:
        return 0.0
    x = T / (2 * pi)
    return x * log(x) - x + 7.0 / 8.0


# public name (the Julia original exports the same symbol)
gof_smooth_counting_function = gof__smooth_counting_function


def gof_unfolded_positions(z):
    return [gof__smooth_counting_function(t) for t in z]


def gof_number_variance(pos, L, n_windows, rng):
    Ltot = pos[-1] - pos[0]
    if Ltot <= L:
        return nan
    counts = []
    for _ in range(n_windows):
        x0 = pos[0] + rng.random() * (Ltot - L)
        lo = bisect_left(pos, x0)
        hi = bisect_left(pos, x0 + L)
        counts.append(float(hi - lo))
    mean = sum(counts) / n_windows
    var = sum((c - mean) * (c - mean) for c in counts)
    return var / (n_windows - 1)


def gof_delta3_rigidity(pos, L, n_windows, n_grid, rng):
    Ltot = pos[-1] - pos[0]
    if Ltot <= L:
        return nan
    xs = [L * float(i) / (n_grid - 1) for i in range(n_grid)]
    total = 0.0
    n_ok = 0
    for _ in range(n_windows):
        x0 = pos[0] + rng.random() * (Ltot - L)
        idx0 = bisect_left(pos, x0)
        Nv = [float(bisect_left(pos, x0 + xs[gi]) - idx0) for gi in range(n_grid)]
        r = gof_linreg(xs, Nv)
        m2 = sum(e * e for e in r.res)
        total += m2 / n_grid
        n_ok += 1
    return total / n_ok


def gof__compute_K_single_seed(eigs, tvals, smooth_window=3):
    """Two-level form factor K(t) — verbatim (local unfold, smooth_window=3)."""
    n = len(eigs)
    K = [0.0] * len(tvals)
    if n < 10:
        return K
    s = sorted(eigs)
    window = max(3, int(round(n * 0.05)))
    u = [0.0] * n
    for i in range(1, n):
        i_lo = max(0, i - window)
        i_hi = min(n - 1, i + window)
        dens = (i_hi - i_lo + 1) / (s[i_hi] - s[i_lo] + 1e-12)
        u[i] = u[i - 1] + (s[i] - s[i - 1]) * dens
    ms = (u[-1] - u[0]) / (n - 1)
    if ms > 1e-12:
        u = [v / ms for v in u]
    for idx, t in enumerate(tvals):
        if t == 0.0:
            K[idx] = 0.0
            continue
        re = 0.0
        im = 0.0
        for k in range(n):
            ph = 2 * pi * t * u[k]
            re += cos(ph)
            im += sin(ph)
        K[idx] = max(0.0, (re * re + im * im) / n)
    w = 3 if smooth_window is None else int(smooth_window)  # callers default 3
    if len(K) > 2 * w:
        Ks = list(K)
        for j in range(w, len(K) - w):
            if tvals[j] < 0.5:
                continue
            acc = 0.0
            cnt = 0
            for q in range(-w, w + 1):
                acc += K[j + q]
                cnt += 1
            Ks[j] = acc / cnt
        K = Ks
    return K


def gof_compute_K_form_factor(eigs, tvals, smooth_window=3):
    return gof__compute_K_single_seed(eigs, tvals, smooth_window=smooth_window)


# ── two-sample helpers (suite Tests 12/34) ──────────────────────────────────

def gof_ks2(a, b):
    """Two-sample KS with tie discipline (ab_cloud_full.jl ks_test_2sample)."""
    xs = sorted(a)
    ys = sorted(b)
    n, m = len(xs), len(ys)
    i = j = 0
    D = 0.0
    while i < n and j < m:
        if xs[i] < ys[j]:
            i += 1
        elif ys[j] < xs[i]:
            j += 1
        else:
            xv = xs[i]
            while i < n and xs[i] == xv:
                i += 1
            while j < m and ys[j] == xv:
                j += 1
        D = max(D, fabs(i / n - j / m))
    return D


def gof_unit_spacings(u):
    d = [u[i + 1] - u[i] for i in range(len(u) - 1)]
    if not d:
        return d
    m = sum(d) / len(d)
    if m > 1e-300:
        d = [v / m for v in d]
    return d


# ═══ KERNEL MODULE: lattice ═══

# -*- coding: utf-8 -*-
"""AB-cloud Hofstadter Hamiltonian — 1:1 with ab_cloud_full.jl §6.

Landau gauge along y: phase (up link) carries 2*pi*alpha*iy (torus wrap:
2*pi*alpha*Ny, requires alpha*Ny integer). Two vortex-phase models:
  - "monumental": smooth gauge on vertical links (ab_phase_vortex_monumental)
  - "dirac":      smooth gauge + Dirac string +-2*pi*q on the same links
Disorder: W>0 residual eps uses the portable classic MT19937 (the Julia
original uses dSFMT — documented divergence; all golden anchors are W=0).

Eigenvalues: cyclic Jacobi for complex Hermitian matrices (no LAPACK;
agrees with zheevr to ~1e-12, inside the golden tolerances).
"""

from math import pi, fabs, sqrt, atan2, floor, sin, cos, isnan
from cmath import exp as cexp, phase as _carg


def lattice__conj(z):
    return z.conjugate()


lattice_MODEL_MONUMENTAL = "monumental"   # smooth vortex gauge on vertical links
lattice_MODEL_DIRAC = "dirac"             # smooth gauge + Dirac string ±2πq


class lattice_Vortex(object):
    __slots__ = ("x", "y", "q")

    def __init__(self, x, y, q):
        self.x = float(x)
        self.y = float(y)
        self.q = float(q)

    def __repr__(self):
        return "Vortex(%r, %r, %r)" % (self.x, self.y, self.q)


class lattice_ABCloudConfig(object):
    def __init__(self, Nx, Ny, vortices, alpha, t, lattice, W,
                 disorder_seed=96, model="monumental"):
        self.Nx = int(Nx)
        self.Ny = int(Ny)
        self.vortices = list(vortices)
        self.alpha = float(alpha)
        self.t = float(t)
        self.lattice = lattice        # "open" | "torus"
        self.W = float(W)
        self.disorder_seed = int(disorder_seed)
        self.model = model            # "monumental" | "dirac"


def lattice_ab_phase_vortex_monumental(ri, rj, vort):
    """Smooth charge-1/2 gauge: phase = sum_k q_k/2 * (theta_kj - theta_ki)."""
    phase = 0.0
    for vk in vort:
        dx1 = ri[0] - vk.x
        dy1 = ri[1] - vk.y
        dx2 = rj[0] - vk.x
        dy2 = rj[1] - vk.y
        a1 = atan2(dy1, dx1) if (dx1 != 0 or dy1 != 0) else 0.0
        a2 = atan2(dy2, dx2) if (dx2 != 0 or dy2 != 0) else 0.0
        phase += vk.q * (a2 - a1) * 0.5
    return phase


def lattice_ab_phase_2d(ri, rj, rk, qk):
    ti = atan2(ri[1] - rk[1], ri[0] - rk[0])
    tj = atan2(rj[1] - rk[1], rj[0] - rk[0])
    return qk * (ti - tj)


def lattice_dirac_string_phase(ri, rj, rk, qk, torus, Nx):
    """Dirac string on vertical links crossing vortex column x=rk[0]."""
    if fabs(ri[0] - rj[0]) > 1e-12:
        return 0.0
    y_lo = min(ri[1], rj[1])
    y_hi = max(ri[1], rj[1])
    if not (y_lo < rk[1] < y_hi):
        return 0.0
    if torus:
        if fabs(ri[0] - float(int(floor(rk[0])))) < 0.5:
            return 0.0
    else:
        if ri[0] <= rk[0]:
            return 0.0
    return -2 * pi * qk if ri[1] < rj[1] else 2 * pi * qk


def lattice_ab_phase_2d_full(ri, rj, rk, qk, torus, Nx):
    return lattice_ab_phase_2d(ri, rj, rk, qk) + \
        lattice_dirac_string_phase(ri, rj, rk, qk, torus, Nx)


def lattice_vortex_onsite_potential(ri, vort, W, N, rng):
    if not vort and W == 0.0:
        return 0.0
    v = 0.0
    ninv = 1.0 / float(max(N, 1))
    for vk in vort:
        dx = ri[0] - vk.x
        dy = ri[1] - vk.y
        v += vk.q * W / ((dx * dx + dy * dy) * ninv + 1.0)
    if W > 0:
        v += (rng.random() - 0.5) * 0.02
    return v


def lattice_build_ab_cloud_hamiltonian(cfg):
    """Return the N x N Hermitian Hamiltonian as a list of lists (complex)."""
    Nx, Ny = cfg.Nx, cfg.Ny
    N = Nx * Ny
    H = [[complex(0.0, 0.0)] * N for _ in range(N)]
    torus = (cfg.lattice == "torus")
    if torus and fabs(cfg.alpha * Ny - round(cfg.alpha * Ny)) >= 1e-10:
        raise AssertionError("torus needs alpha*Ny integer")
    rng = mt19937_MT19937(cfg.disorder_seed & 0xFFFFFFFF)
    for iy in range(1, Ny + 1):
        for ix in range(1, Nx + 1):
            i = (iy - 1) * Nx + ix - 1
            ri = (float(ix), float(iy))
            # right neighbour
            jx, jy, wrap = ix + 1, iy, False
            if jx > Nx:
                if torus:
                    jx, wrap = 1, True
                else:
                    jx = 0
            if jx != 0:
                j = (jy - 1) * Nx + jx - 1
                phi = 2 * pi * cfg.alpha * iy
                if cfg.model == "dirac":
                    rjp = (float(Nx + 1) if wrap else float(jx), float(jy))
                    for v in cfg.vortices:
                        rk = (v.x, v.y)
                        phi += lattice_ab_phase_2d_full(ri, rjp, rk, v.q, torus, Nx)
                hop = -cfg.t * cexp(complex(0.0, phi))
                H[i][j] += hop
                H[j][i] += lattice__conj(hop)
            # up neighbour
            jx, jy, wrap = ix, iy + 1, False
            if jy > Ny:
                if torus:
                    jy, wrap = 1, True
                else:
                    jy = 0
            if jy != 0:
                j = (jy - 1) * Nx + jx - 1
                phi = 2 * pi * cfg.alpha * Ny if wrap else 0.0
                rjp = (float(ix), float(iy) + 1.0)   # unwrapped top
                if cfg.model == "monumental":
                    phi += lattice_ab_phase_vortex_monumental(ri, rjp, cfg.vortices)
                else:
                    for v in cfg.vortices:
                        rk = (v.x, v.y)
                        phi += lattice_ab_phase_2d_full(ri, rjp, rk, v.q, torus, Nx)
                hop = -cfg.t * cexp(complex(0.0, phi))
                H[i][j] += hop
                H[j][i] += lattice__conj(hop)
            H[i][i] += lattice_vortex_onsite_potential(ri, cfg.vortices, cfg.W, N, rng)
    # Hermitian symmetrization (H + H^dagger)/2
    for r in range(N):
        Hr = H[r]
        for c in range(r + 1, N):
            a = Hr[c]
            b = H[c][r]
            m = 0.5 * (a + lattice__conj(b))
            Hr[c] = m
            H[c][r] = lattice__conj(m)
    # numpy array — the HP stack layer uses H.conj().T and vectorized ops
    import numpy as np
    return np.array(H, dtype=complex)


def lattice_jacobi_eigvals(H, max_sweeps=60):
    """Cyclic Jacobi for complex Hermitian matrices -> sorted real eigenvalues.

    Operates on a deep copy; H is a list of lists of complex.
    """
    N = len(H)
    A = [list(row) for row in H]   # copy (np rows would alias the input)
    off_norm0 = 0.0
    for r in range(N):
        Ar = A[r]
        for c in range(r + 1, N):
            off_norm0 += abs(Ar[c]) ** 2
    thresh = 1e-15 * sqrt(2.0 * off_norm0 + 1e-300)
    for _ in range(max_sweeps):
        off = 0.0
        for r in range(N):
            Ar = A[r]
            for c in range(r + 1, N):
                off += abs(Ar[c]) ** 2
        if sqrt(2.0 * off) < thresh:
            break
        for p in range(N - 1):
            for q in range(p + 1, N):
                apq = A[p][q]
                if abs(apq) <= thresh:
                    continue
                app = A[p][p].real
                aqq = A[q][q].real
                tau = (aqq - app) / (2.0 * abs(apq))
                t = (1.0 if tau >= 0 else -1.0) / (fabs(tau) + sqrt(1.0 + tau * tau))
                c = 1.0 / sqrt(1.0 + t * t)
                s = t * c                      # normalized rotation (tan = t)
                ph = apq / abs(apq)            # e^{i phi}
                se = s * ph                    # s * e^{i phi}
                sec = lattice__conj(se)
                # rows/cols p,q update: A' = G^dagger A G
                for k in range(N):
                    if k == p or k == q:
                        continue
                    Ak = A[k]
                    akp = Ak[p]
                    akq = Ak[q]
                    nkp = c * akp - sec * akq
                    nkq = se * akp + c * akq
                    Ak[p] = nkp
                    A[p][k] = lattice__conj(nkp)
                    Ak[q] = nkq
                    A[q][k] = lattice__conj(nkq)
                npp = app - t * abs(apq)
                nqq = aqq + t * abs(apq)
                A[p][p] = complex(npp, 0.0)
                A[q][q] = complex(nqq, 0.0)
                A[p][q] = complex(0.0, 0.0)
                A[q][p] = complex(0.0, 0.0)
    ev = sorted(A[r][r].real for r in range(N))
    return ev


def lattice_safe_eigvals(H):
    return lattice_jacobi_eigvals(H)


def lattice_plaquette_flux(H, Nx, Ny, ix, iy, torus=False):
    """CCW sum of arg(-H[b,a]) around the elementary plaquette at (ix, iy)."""
    ix_r = (ix % Nx) + 1 if torus else ix + 1
    iy_t = (iy % Ny) + 1 if torus else iy + 1
    i_bl = (iy - 1) * Nx + ix - 1
    i_br = (iy - 1) * Nx + ix_r - 1
    i_tr = (iy_t - 1) * Nx + ix_r - 1
    i_tl = (iy_t - 1) * Nx + ix - 1
    fb = _carg(-H[i_br][i_bl])
    fr = _carg(-H[i_tr][i_br])
    ft = _carg(-H[i_tl][i_tr])
    fl = _carg(-H[i_bl][i_tl])
    return fb + fr + ft + fl


def lattice_flux_circdist(a, b):
    m = (a - b + pi) % (2 * pi)
    return fabs(m - pi)


def lattice_central_band_eigs(s, frac):
    """Central band: floor(n*frac/2) levels on each side of the spectrum middle."""
    n = len(s)
    if n == 0:
        return []
    frac = min(max(frac, 0.05), 1.0)
    if frac >= 1.0:
        return list(s)
    half = int(floor(n * frac / 2.0))
    j_lo = max(1, n // 2 - half)
    j_hi = min(n, n // 2 + half)
    return [s[j - 1] for j in range(j_lo, j_hi + 1)]


def lattice_chiral_symmetry_defect(H, Nx, Ny):
    """||S H S + H||_F / ||H||_F with S_{(ix,iy)} = (-1)^{ix+iy} — streamed."""
    N = Nx * Ny
    norm_h = 0.0
    num = 0.0
    for r in range(N):
        sr = 1 if (((r % Nx) + 1) + (r // Nx + 1)) % 2 == 0 else -1
        Hr = H[r]
        for c in range(N):
            sc = 1 if (((c % Nx) + 1) + (c // Nx + 1)) % 2 == 0 else -1
            v = (sr * sc) * Hr[c] + Hr[c]
            num += abs(v) ** 2
            norm_h += abs(Hr[c]) ** 2
    return sqrt(num) / max(sqrt(norm_h), 1e-30)


def lattice_verify_hermitian(H):
    N = len(H)
    max_err = 0.0
    norm_m = 0.0
    for r in range(N):
        Hr = H[r]
        for c in range(N):
            norm_m += abs(Hr[c]) ** 2
            err = abs(Hr[c] - lattice__conj(H[c][r]))
            if err > max_err:
                max_err = err
    return max_err / max(sqrt(norm_m), 1e-30) < 1e-12


def lattice_time_reversal_asymmetry(H):
    diff = 0.0
    norm_m = 0.0
    for row in H:
        for v in row:
            norm_m += abs(v) ** 2
            diff += abs(v - lattice__conj(v)) ** 2
    return sqrt(diff) / max(sqrt(norm_m), 1e-30)


# ═══ KERNEL MODULE: unfold ═══

# -*- coding: utf-8 -*-
"""HP-аудит: развёртка, регрессия и H1-детектор — 1:1 с ab_cloud_full.jl §7
и hp_audit_standalone.jl (детектор H1 + вспомогательная статистика)."""

from math import log, sqrt, fabs, pi, cos, sin, exp, isnan


def unfold_hp_kgue_envelope(t):
    """GUE form-factor envelope K_box(t): t*(1-sinc(2pi t)) for t<1, else 1."""
    if t < 1.0:
        x = 2 * pi * t
        sn = 1.0 if fabs(x) < 1e-12 else sin(x) / x
        return t * (1.0 - sn)
    return 1.0


def unfold_hp_raw_ft(zs, omega):
    """H1 periodogram: |sum_i Hann(t_i) e^{-i omega z_i}|^2 / sum Hann^2."""
    n = len(zs)
    w = [0.5 * (1.0 - cos(2 * pi * i / max(n - 1, 1))) for i in range(n)]
    sw2 = sum(wi * wi for wi in w)
    P = []
    for om in omega:
        re = 0.0
        im = 0.0
        for i in range(n):
            re += w[i] * cos(om * zs[i])
            im -= w[i] * sin(om * zs[i])
        P.append((re * re + im * im) / sw2)
    return P


def unfold_hp_unfold_local(eigs, win_frac=0.05):
    """Local-density unfolding with window = max(3, round(n*win_frac))."""
    s = sorted(eigs)
    n = len(s)
    if n < 10:
        return [float(i) for i in range(n)]
    window = max(3, int(round(n * win_frac)))
    u = [0.0] * n
    for i in range(1, n):
        i_lo = max(0, i - window)
        i_hi = min(n - 1, i + window)
        dens = (i_hi - i_lo + 1) / (s[i_hi] - s[i_lo] + 1e-12)
        u[i] = u[i - 1] + (s[i] - s[i - 1]) * dens
    ms = (u[-1] - u[0]) / max(n - 1, 1)
    if ms > 1e-12:
        u = [v / ms for v in u]
    return u


def unfold_hp_k_residual(K, tvals, dpoly=3):
    """K(t) residual for H1 (Julia _hp_k_residual): measured form factor minus
    the analytic GUE envelope, then a degree-`dpoly` polynomial detrend (least
    squares on the full window — a quadratic cannot absorb the log-p
    oscillations whose periods are >= 2.45)."""
    import numpy as np
    base = [unfold_hp_kgue_envelope(t) for t in tvals]
    res = [K[i] - base[i] for i in range(len(tvals))]
    X = np.array([[float(t) ** k for k in range(dpoly + 1)] for t in tvals])
    y = np.array(res)
    coef, _, _, _ = np.linalg.lstsq(X, y, rcond=None)
    out = y - X @ coef
    return [float(v) for v in out]


def unfold_hp_periodogram(res, ts, omega):
    """H1 D2 route (Julia _hp_periodogram): mean-subtracted Hann-weighted FT of
    a residual series over the UNFOLDING time axis, P = 2|sum|^2 / sum w^2."""
    n = len(res)
    if n == 0:
        return [0.0] * len(omega)
    m = sum(res) / n
    r = [v - m for v in res]
    w = [0.5 * (1.0 - cos(2 * pi * k / max(n - 1, 1))) for k in range(n)]
    sw2 = sum(wi * wi for wi in w)
    if not sw2 > 1e-300:
        sw2 = 1.0
    t0 = ts[0]
    P = []
    for om in omega:
        acc_re = 0.0
        acc_im = 0.0
        for k in range(n):
            ph = om * (ts[k] - t0)
            wk = w[k] * r[k]
            acc_re += wk * cos(ph)
            acc_im -= wk * sin(ph)
        P.append(2.0 * (acc_re * acc_re + acc_im * acc_im) / sw2)
    return P


def unfold_hp_fluct_hp(f, win=8):
    """H7 fluctuation high-pass (Julia _hp_fluct_hp): subtract the centered
    moving average (half-width `win`) from a fluctuation series — removes the
    slow deterministic estimator bias shared by every spectrum processed with
    the same local-window unfolding."""
    n = len(f)
    win = max(1, min(win, n // 2))
    out = []
    for i in range(n):
        lo = max(0, i - win)
        hi = min(n, i + win + 1)
        seg = f[lo:hi]
        out.append(f[i] - sum(seg) / len(seg))
    return out


def unfold_hp_unit_spacings(u):
    """Unit spacings (mean 1) — alias used by the HP gates."""
    return unfold_unit_spacings(u)


def unfold_unit_spacings(u):
    return gof_unit_spacings(u)


def unfold_hp_rankdata(x):
    """1-based average ranks (ties get the mean rank)."""
    n = len(x)
    ord_ = sorted(range(n), key=lambda i: x[i])
    ranks = [0.0] * n
    i = 0
    while i < n:
        j = i
        while j + 1 < n and x[ord_[j + 1]] == x[ord_[i]]:
            j += 1
        avg = (i + j) / 2.0 + 1.0
        for k in range(i, j + 1):
            ranks[ord_[k]] = avg
        i = j + 1
    return ranks


def unfold_pearson_cor(x, y):
    n = len(x)
    if n == 0:
        return float("nan")
    mx = sum(x) / n
    my = sum(y) / n
    sxy = sxx = syy = 0.0
    for xi, yi in zip(x, y):
        sxy += (xi - mx) * (yi - my)
        sxx += (xi - mx) * (xi - mx)
        syy += (yi - my) * (yi - my)
    if sxx <= 0 or syy <= 0:
        return float("nan")
    return sxy / sqrt(sxx * syy)


def unfold_hp_aicc(n, rss, k):
    """Akaike information criterion with small-sample correction."""
    denom = n - k - 1
    aic = n * log(max(rss, 1e-300) / n) + 2.0 * k
    return aic + 2.0 * k * (k + 1) / denom if denom > 0 else aic


def unfold_hp_wald_ci(k, n):
    """Wald 95% interval for a proportion k/n -> (p, lo, hi)."""
    if n == 0:
        return 0.0, 0.0, 0.0
    p = float(k) / n
    h = 1.96 * sqrt(p * (1 - p) / n)
    lo = min(max(p - h, 0.0), 1.0)
    hi = min(max(p + h, 0.0), 1.0)
    return p, lo, hi


def unfold_default_omega_grid():
    """726-point band [0.3, 3.2] step 0.004 — the H1 default scan grid."""
    return [0.3 + 0.004 * k for k in range(726)]


def unfold_h1_detect(zs, omega=None):
    """H1 primary detector: SNR of log-prime harmonics against band median."""
    if omega is None:
        omega = unfold_default_omega_grid()
    P = unfold_hp_raw_ft(zs, omega)
    Ps = sorted(P)
    n = len(Ps)
    med = Ps[n // 2] if n % 2 == 1 else 0.5 * (Ps[n // 2 - 1] + Ps[n // 2])
    out = []
    for pr in (2, 3, 5, 7, 11, 13):
        tgt = log(pr)
        best = 0
        bd = 1e300
        for i, om in enumerate(omega):
            d = fabs(om - tgt)
            if d < bd:
                bd = d
                best = i
        out.append((pr, P[best] / med))
    return med, out


def unfold_h1_report(zs, omega=None, snr_gate=10.0):
    """Full H1 report: median, per-prime SNR verdicts, aggregate verdict."""
    med, snrs = unfold_h1_detect(zs, omega)
    hits = 0
    lines = []
    for pr, snr in snrs:
        peak = snr >= snr_gate
        hits += 1 if peak else 0
        lines.append("  SNR(log %2d) = %.6e  [%s]" % (pr, snr, "PEAK" if peak else "-"))
    verdict = "%d/6 prime harmonics above SNR %g" % (hits, snr_gate)
    strong = all(snr >= 100.0 for _, snr in snrs)
    return {
        "median": med,
        "snrs": snrs,
        "hits": hits,
        "verdict": verdict,
        "strong": strong,
        "lines": lines,
    }


# ═══ KERNEL MODULE: hp_audit ═══

# -*- coding: utf-8 -*-
"""HP-audit computational core — port of hp_audit_standalone.jl detectors.

The full HP-аудит includes a hand-rolled PNG graphics engine (lines 1–2000
of the original) and an interactive shell — those are presentation layers,
NOT physics, and are intentionally out of scope for the port (use the Julia
original for the rendered reports).  What is ported here is the complete
H1 detector machinery and its verdict protocol:

  D1 — raw-position periodogram with a Hann index window
       P(ω) = |Σₖ wₖ e^{−iωTₖ}|² / Σwₖ²  (unfold-free — the Riemann–Weil
       explicit formula makes the zero-density fluctuation a sum of PURE
       TONES in the raw ordinate T, so arithmetic content shows Bragg
       peaks at ω = log p and harmonics k·log p);
  SNR yardstick — P(log p)/median(P) over the scanned band
       (empirically calibrated: ζ control 10⁶–10⁹, GUE/vortex-free
       nulls ≤ 5);
  band scan — ω ∈ [0.3, 3.2] step 0.004 (covers log 2 … log 25);
  D2 — K(t)-residual route (form factor minus GUE envelope, polynomial
       detrend) — retained as a cross-check, intrinsically less sensitive.

Gate conventions (hp_audit_standalone.jl):
  H1 PASS  — ≥ 4 of the 6 prime harmonics (p = 2,3,5,7,11,13) above
             SNR 10 on the same scan;
  H1 STRONG — every SNR above 100.
"""

import math


hp_audit_PRIMES = (2, 3, 5, 7, 11, 13)
hp_audit_OMEGA_MIN = 0.3
hp_audit_OMEGA_MAX = 3.2
hp_audit_OMEGA_STEP = 0.004
hp_audit_SNR_PEAK = 10.0
hp_audit_SNR_STRONG = 100.0


def hp_audit_default_omega_grid():
    """The audit's band grid: 0.3:0.004:3.2 (726 points)."""
    n = int(round((hp_audit_OMEGA_MAX - hp_audit_OMEGA_MIN) / hp_audit_OMEGA_STEP)) + 1
    return [hp_audit_OMEGA_MIN + hp_audit_OMEGA_STEP * k for k in range(n)]


def hp_audit_nearest_index(grid, omega):
    """First index of the closest grid point (Julia argmin semantics)."""
    best_i, best_d = 0, abs(grid[0] - omega)
    for i in range(1, len(grid)):
        d = abs(grid[i] - omega)
        if d < best_d:
            best_i, best_d = i, d
    return best_i


def hp_audit_median(v):
    s = sorted(v)
    n = len(s)
    mid = n // 2
    return s[mid] if n % 2 == 1 else (s[mid - 1] + s[mid]) / 2.0


def hp_audit_h1_detect(positions, omega_grid=None):
    """Run the H1 primary detector on sorted positions Tₖ.

    Returns dict with the band median and per-prime SNRs."""
    if omega_grid is None:
        omega_grid = hp_audit_default_omega_grid()
    P = unfold_hp_raw_ft(list(positions), omega_grid)
    med = hp_audit_median(P)
    out = {"n_positions": len(positions), "band_median": med,
           "n_freq": len(omega_grid), "snr": {}}
    for p in hp_audit_PRIMES:
        i = hp_audit_nearest_index(omega_grid, math.log(p))
        out["snr"][p] = P[i] / med
    n_peaks = sum(1 for v in out["snr"].values() if v >= hp_audit_SNR_PEAK)
    n_strong = sum(1 for v in out["snr"].values() if v >= hp_audit_SNR_STRONG)
    out["n_peaks"] = n_peaks
    out["n_strong"] = n_strong
    out["verdict"] = ("STRONG" if n_strong == len(hp_audit_PRIMES)
                      else "PASS" if n_peaks >= 4 else "NO SIGNAL")
    return out


def hp_audit_h1_report(positions, title="H1 detector"):
    """Human-readable H1 report (computational part of the audit gate)."""
    res = hp_audit_h1_detect(positions)
    lines = [f"{title}: n={res['n_positions']} positions, "
             f"{res['n_freq']} freqs, band median {res['band_median']:.6e}"]
    for p in hp_audit_PRIMES:
        snr = res["snr"][p]
        mark = "PEAK" if snr >= hp_audit_SNR_PEAK else "—"
        strong = " (strong)" if snr >= hp_audit_SNR_STRONG else ""
        lines.append(f"  SNR(log {p:2d}) = {snr:.6e}  [{mark}]{strong}")
    lines.append(f"  verdict: {res['verdict']} "
                 f"({res['n_peaks']}/6 above SNR {hp_audit_SNR_PEAK:.0f})")
    return res, "\n".join(lines)


def hp_audit_h1_null_control(eigs, omega_grid=None):
    """Null control on a lattice (vortex-free) spectrum: the same detector
    must NOT find prime harmonics (SNR ≤ 5 calibrated band)."""
    res = hp_audit_h1_detect(eigs, omega_grid)
    res["expected"] = "no peaks (SNR ≤ 5)"
    return res


def hp_audit_k_residual_rms(eigs, tvals, dpoly: int = 3) -> float:
    """D2 cross-check: RMS of the polynomially detrended K(t) residual
    against the connected GUE envelope."""
    K = gof_compute_K_form_factor(eigs, tvals)
    res = unfold_hp_k_residual(K, tvals, dpoly=dpoly)
    return math.sqrt(sum(r * r for r in res) / len(res))


