# ══════════════════════════════════════════════════════════════════════════════
# AURORA CONSOLE LAYER — HP·MERIDIAN identity for the unified standalone.
# ◆ block-letter wordmark through a cyan→violet→gold truecolor gradient;
# ❖ section rules; ⟦ ⟧ diamond badges; braille ladder bars ⣀⣄⣤⣦⣶⣷⣿ on a
# slate ⣀ track; kv-rows; the interactive menu; the doctor probe.
# Console text stays English (report-plain), file headers stay Russian.
# ══════════════════════════════════════════════════════════════════════════════

_AURORA_MODE = "none"


def _aurora_mode_probe():
    """truecolor → ansi16 → none, honoring NO_COLOR / FORCE_COLOR / TTY."""
    global _AURORA_MODE
    if os.environ.get("NO_COLOR"):
        _AURORA_MODE = "none"
    elif os.environ.get("FORCE_COLOR"):
        _AURORA_MODE = "truecolor"
    elif sys.stdout.isatty() and os.environ.get("TERM") not in ("dumb", ""):
        _AURORA_MODE = "truecolor" if os.environ.get("COLORTERM") else "ansi16"
    else:
        _AURORA_MODE = "none"
    return _AURORA_MODE


def _R():
    """Dynamic reset — mode is probed at runtime, not import time."""
    return "\x1b[0m" if _AURORA_MODE != "none" else ""


def _rgb(r, g, b):
    if _AURORA_MODE == "truecolor":
        return "\x1b[38;2;%d;%d;%dm" % (max(0, min(255, int(r))),
                                        max(0, min(255, int(g))),
                                        max(0, min(255, int(b))))
    return ""


def _c(txt, key="fg"):
    """AURORA palette keys: fg dim ok warn bad gold vio cyan mint sky rose."""
    if _AURORA_MODE == "none":
        return str(txt)
    pal = {"fg": (214, 226, 235), "dim": (108, 124, 138), "ok": (126, 231, 135),
           "warn": (255, 199, 95), "bad": (255, 107, 107), "gold": (255, 215, 95),
           "vio": (167, 130, 255), "cyan": (97, 218, 251), "mint": (125, 255, 212),
           "sky": (143, 216, 255), "rose": (255, 143, 196)}
    r, g, b = pal.get(key, pal["fg"])
    return _rgb(r, g, b) + str(txt) + _R()


def _grad_rgb(t):
    """cyan (97,218,251) → violet (167,130,255) → gold (255,215,95), t∈[0,1]."""
    stops = [(0.0, (97, 218, 251)), (0.5, (167, 130, 255)), (1.0, (255, 215, 95))]
    t = max(0.0, min(1.0, t))
    for (t0, c0), (t1, c1) in zip(stops, stops[1:]):
        if t <= t1:
            k = (t - t0) / (t1 - t0)
            return tuple(c0[i] + k * (c1[i] - c0[i]) for i in range(3))
    return stops[-1][1]


def _grad(txt):
    """Paint a plain row through the AURORA gradient column by column."""
    if _AURORA_MODE == "none":
        return txt
    n = len(txt)
    out = []
    for i, ch in enumerate(txt):
        if ch == " ":
            out.append(ch)
            continue
        r, g, b = _grad_rgb(n <= 1 and 0.5 or (i + 0.5) / n)
        out.append(_rgb(r, g, b) + ch)
    out.append(_R())
    return "".join(out)


