def _bigtext(word):
    rows = ["", "", "", "", "", ""]
    for ch in word:
        gl = _BIGFONT.get(ch)
        if gl is None:
            continue
        for i in range(6):
            rows[i] += gl[i] + " "
    return rows


def _badge(txt, key="gold"):
    return _c("⟦ ", "dim") + _c(txt, key) + _c(" ⟧", "dim")


def _rule(ch="❖", width=78, key="vio"):
    return _c("─" * 3 + " " + ch + " " + "─" * (width - 7), key)


def _bar(p, width=28):
    """Braille ladder ⣀⣄⣤⣦⣶⣷⣿ over a slate ⣀ track, gradient-filled."""
    lad = "⣀⣄⣤⣦⣶⣷⣿"
    p = max(0.0, min(1.0, p))
    full = int(p * width)
    frac = p * width - full
    cells = []
    for i in range(width):
        if i < full:
            k = (i + 1) / width
            col = ""
            if _AURORA_MODE != "none":
                r, g, b = _grad_rgb(k)
                col = _rgb(r, g, b)
            cells.append(col + "⣿" + _R())
        elif i == full and frac > 0.02:
            cells.append(_c(lad[min(6, int(frac * 7))], "dim"))
        else:
            cells.append(_c("⣀", "dim"))
    return "".join(cells) + _c(" %5.1f%%" % (p * 100), "dim")


def _kv(k, v, width=30):
    pad = "." * max(2, width - len(k))
    return _c("  " + k + " ", "fg") + _c(pad, "dim") + " " + _c(str(v), "gold")


def _banner(word="AB·CLOUD", subtitle="MERIDIAN OBSERVATORY · UNIFIED STANDALONE"):
    """Block-letter wordmark, gradient-shaded, with the identity frame."""
    print()
    for row in _bigtext(word):
        print("  " + _grad(row))
    print("  " + _c("═" * 66, "dim"))
    print("  " + _grad("◆ " + subtitle + " ◆"))
    print("  " + _c("brand: AB·CLOUD · MERIDIAN OBSERVATORY UNIFIED STANDALONE",
                    "dim"))
    print("  " + _rule())


def _identity_frame(lines):
    """❖ diamond identity frame — used by verdict blocks and menu header."""
    w = max(len(l) for l in lines) + 8
    print("  " + _c("◆" + "─" * (w - 2) + "◆", "vio"))
    for l in lines:
        print("  " + _c("│  ", "vio") + l)
    print("  " + _c("◆" + "─" * (w - 2) + "◆", "vio"))


def _progress(title, total, fn):
    """Braille-ladder progress over an iterable, ✓-done frame."""
    print("  " + _c(title, "cyan"))
    out = []
    for i, item in enumerate(fn()):
        out.append(item)
        p = (i + 1) / float(total)
        sys.stdout.write("\r  " + _bar(p) + "\x1b[0K")
        sys.stdout.flush()
    sys.stdout.write("\n")
    return out


def _doctor():
    """Environment probe: numpy, threads, color mode, embedded payloads."""
    print()
    print("  " + _c("◆ DOCTOR — environment probe", "vio"))
    print("  " + _rule())
    rows = []
    rows.append(("python", sys.version.split()[0]))
    try:
        import numpy as _np
        rows.append(("numpy", _np.__version__))
    except Exception:
        rows.append(("numpy", "MISSING (eigen paths will fail)"))
    rows.append(("color mode", _AURORA_MODE))
    rows.append(("term", os.environ.get("TERM", "?")))
    rows.append(("embedded blobs", ", ".join(_AB_EMB_NAMES)))
    rows.append(("zeros50k", "%d values" % len(_ab_load_zeros_emb(":emb:zeros50k"))))
    try:
        g = _ab_load_json_emb(":emb:golden")
        rows.append(("golden", "%d sections" % len(g)))
    except Exception as exc:
        rows.append(("golden", "ERROR: %r" % (exc,)))
    try:
        gs = _ab_load_json_emb(":emb:golden_stk")
        rows.append(("golden stack", "%d sections" % len(gs)))
    except Exception as exc:
        rows.append(("golden stack", "ERROR: %r" % (exc,)))
    ok = all("ERROR" not in str(v) and "MISSING" not in str(v)
             for k, v in rows)
    for k, v in rows:
        print(_kv("%-14s" % k, v))
    verdict = _badge("SANE", "ok") if ok else _badge("UNHEALTHY", "bad")
    print("  verdict: " + verdict)
    return ok


# ═══ PNG PLOT ENGINE (600 dpi) ═══

# ══════════════════════════════════════════════════════════════════════════════
# AURORA PLOTS — dependency-free 600-dpi PNG engine.
# Stored-deflate PNG writer (CRC32 + adler32, zero imports), stroke-font
# renderer, ss=2 supersampled canvas box-downsampled to 3600×2250 output.
# Charts carry numeric annotations in the user's report language (en).
# ══════════════════════════════════════════════════════════════════════════════

_AB_CRC_TAB = []


def _ab_crc32(data):
    global _AB_CRC_TAB
    if not _AB_CRC_TAB:
        for n in range(256):
            c = n
            for _ in range(8):
                c = ((c >> 1) ^ 0xEDB88320) & 0xFFFFFFFF if c & 1 else (c >> 1)
            _AB_CRC_TAB.append(c)
    c = 0xFFFFFFFF
    for b in data:
        c = _AB_CRC_TAB[(c ^ b) & 0xFF] ^ (c >> 8)
    return c ^ 0xFFFFFFFF


def _ab_adler32(data):
    a, b = 1, 0
    for byte in data:
        a = (a + byte) % 65521
        b = (b + a) % 65521
    return ((b << 16) | a) & 0xFFFFFFFF


def _ab_png_chunk(tag, payload):
    return (len(payload).to_bytes(4, "big") + tag + payload +
            _ab_crc32(tag + payload).to_bytes(4, "big"))


def _ab_png_encode(rgba, w, h):
    """rgba: bytearray w*h*4, row-major. stdlib-zlib IDAT (small files)."""
    raw = bytearray()
    stride = w * 4
    for y in range(h):
        raw.append(0)
        raw += rgba[y * stride:(y + 1) * stride]
    z = _zlibmod.compress(bytes(raw), 6)
    ihdr = (w).to_bytes(4, "big") + (h).to_bytes(4, "big") + bytes([8, 6, 0, 0, 0])
    return (b"\x89PNG\r\n\x1a\n" + _ab_png_chunk(b"IHDR", ihdr) +
            _ab_png_chunk(b"IDAT", z) + _ab_png_chunk(b"IEND", b""))


